# 45 private equity firms: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("blackstone","Blackstone","https://www.blackstone.com/","Peter G. Peterson and Stephen Schwarzman founded Blackstone in New York in 1985.","A plain serif wordmark with no symbol feels like a law firm or a bank.","The name itself is a translation of both founders' surnames, so the logo can stay quiet."),
("kkr","KKR","https://www.kkr.com/","Jerome Kohlberg, Henry Kravis and George Roberts founded KKR in 1976.","Three wide letters make the founders' initials the whole logo.","Deep purple instead of blue or black sets it apart from most finance logos."),
("the-carlyle-group","The Carlyle Group","https://www.carlyle.com/","David Rubenstein, William Conway and Daniel D'Aniello founded Carlyle in Washington, D.C., in 1987, and named it after the Carlyle Hotel in New York.","Small-capital serif type looks like an old banking letterhead.","Two thin lines and a strapline frame the name like a certificate."),
("apollo","Apollo","https://www.apollo.com/","Leon Black, Josh Harris and Marc Rowan founded Apollo in 1990.","Widely spaced serif capitals feel classical, like the Greek god it is named after.","A deep green is unusual for finance and suggests money and growth."),
("tpg","TPG","https://www.tpg.com/","David Bonderman and James Coulter founded the firm in 1992 as Texas Pacific Group.","A three-letter acronym replaced the original longer name.","A striped graphic block beside the letters adds movement to a plain wordmark."),
("bain-capital","Bain Capital","https://www.baincapital.com/","Bain Capital was founded in Boston in 1984 by partners from Bain & Company.","A blue and red mark looks like a folded flag or ribbon.","The name is written in one word with a capital C, a modern touch."),
("warburg-pincus","Warburg Pincus","https://www.warburgpincus.com/","Warburg Pincus traces its roots to 1966, when E.M. Warburg and Lionel Pincus joined forces in New York.","Elegant small capitals link two family names with a classic serif.","Teal-blue ink feels calmer than the usual navy of finance."),
("brookfield","Brookfield","https://www.brookfield.com/","Brookfield traces its history to 1899 in Brazil, and is now a global investor in infrastructure, real estate and energy.","Heavy sans serif letters look strong and industrial.","The simple name suits a company that owns bridges, power and property."),
("ares-management","Ares Management","https://www.aresmgmt.com/","Ares was founded in Los Angeles in 1997 and is named after the Greek god of war.","A swirling A on the left is a monogram with a touch of calligraphy.","The condensed serif feels modern and confident."),
("eqt","EQT","https://eqtgroup.com/","EQT was founded in Stockholm in 1994 with backing from Sweden's Wallenberg family.","Three blocky letters are drawn with sharp, geometric cuts.","The Q has a distinctive notch that makes a very short name memorable."),
("cvc","CVC","https://www.cvc.com/","CVC began in 1981 as Citicorp Venture Capital and became independent in 1993.","Three thin capitals are almost a monogram.","A very light weight makes the firm feel calm and elite."),
("permira","Permira","https://www.permira.com/","Permira was founded in London in 1985 and took its current name in 2001.","Widely spaced capitals feel airy and international.","Orange flames above the I give a small spark to a quiet wordmark."),
("advent-international","Advent International","https://www.adventinternational.com/","Peter Brooke founded Advent in Boston in 1984.","A yellow dot replaces the point of the A, a small, memorable detail.","A sharp serif gives the logo a classic, editorial look."),
("cinven","Cinven","https://www.cinven.com/","Cinven was founded in London in 1977.","A solid teal block with white letters looks like a sign or a stamp.","The bright teal sets it apart from sober navy competitors."),
("apax-partners","Apax Partners","https://www.apax.com/","Apax traces its roots to 1972 and is based in London.","The X ends in a bold arrow-like cut, giving the logo direction.","A short name in heavy sans serif feels modern and direct."),
("bc-partners","BC Partners","https://www.bcpartners.com/","BC Partners was founded in London in 1986.","A blue diagonal frame holds the name like a window.","Mixed weights separate the initials from the word Partners."),
("partners-group","Partners Group","https://www.partnersgroup.com/","Partners Group was founded in Zug, Switzerland, in 1996.","A red bar sits behind the word Group, a simple graphic anchor.","Stacked capitals make a long name compact."),
("hg","Hg","https://hgcapital.com/","Hg is a London firm focused on software and services, with roots in Mercury Private Equity from the 1990s.","The two letters are the chemical symbol for mercury, a nod to its past.","A small red flag on the g adds one accent to a monochrome mark."),
("thoma-bravo","Thoma Bravo","https://www.thomabravo.com/","Thoma Bravo traces its roots to 1980 and focuses on software.","A bold block mark sits to the left of the name.","The two names are set as one word, which makes it feel like a tech brand."),
("vista-equity-partners","Vista Equity Partners","https://www.vistaequitypartners.com/","Robert F. Smith founded Vista in 2000 to invest in enterprise software.","A V with a swoosh looks like a check mark or a bird in flight.","Very widely spaced capitals feel premium."),
("silver-lake","Silver Lake","https://www.silverlake.com/","Silver Lake was founded in Menlo Park, California, in 1999 and focuses on technology.","Small capitals with a hint of tech feel modern but serious.","The two words make the firm sound like a place, not a financial company."),
("general-atlantic","General Atlantic","https://www.generalatlantic.com/","Charles Feeney founded General Atlantic in 1980.","Two stacked blocks and diagonal strokes look like waves.","Dark teal ties the name to the ocean in the middle of it."),
("insight-partners","Insight Partners","https://www.insightpartners.com/","Insight Partners was founded in New York in 1995 and invests in software and growth companies.","The giant orange INSIGHT is the loudest wordmark in the group.","Small, widely spaced PARTNERS underneath balances the heavy word."),
("francisco-partners","Francisco Partners","https://www.franciscopartners.com/","Francisco Partners was founded in San Francisco in 1999 and focuses on technology.","A stacked F and P monogram looks like a classic monogram stamp.","Serif type for the full name makes it feel established."),
("summit-partners","Summit Partners","https://www.summitpartners.com/","Summit Partners was founded in Boston in 1984 and invests in growth companies.","A mountain peak is a direct visual for the name Summit.","Spaced capitals keep the focus on the symbol."),
("ta-associates","TA Associates","https://www.ta.com/","TA Associates was founded in Boston in 1968, one of the oldest private equity firms in the US.","Two letters in a square look like a monogram stamp.","A thick outline gives a very short name weight."),
("accel-kkr","Accel-KKR","https://www.accel-kkr.com/","Accel-KKR was founded in 2000 as a software investor backed by Accel Partners and KKR.","Serif capitals in a box feel like a stock certificate.","A thin underline and small text show its dual parentage."),
("hellman-and-friedman","Hellman & Friedman","https://www.hfriedman.com/","Hellman & Friedman was founded in San Francisco in 1984.","An ampersand joins the two founders' names in a clean serif.","The name is simply set, which suits a firm that avoids publicity."),
("clayton-dubilier-and-rice","Clayton, Dubilier & Rice","https://www.cdr-inc.com/","Clayton, Dubilier & Rice was founded in New York in 1978.","The initials are shortened to a compact CD&R mark.","The white box and simple serif feel like a law firm."),
("leonard-green-and-partners","Leonard Green & Partners","https://www.leonardgreen.com/","Leonard Green & Partners was founded in Los Angeles in 1989.","A green LGP monogram anchors the name.","Green on white is unusual among private equity firms."),
("genstar-capital","Genstar Capital","https://www.genstarcapital.com/","Genstar Capital was founded in San Francisco in 1988.","Red bars rise above the name like a small bar chart.","The blue wordmark and red chart are simple and symbolic."),
("thomas-h-lee-partners","Thomas H. Lee Partners","https://www.thl.com/","Thomas H. Lee founded the firm in Boston in 1974.","THL in a blue box is an initial stamp.","The thick outline makes a short mark feel solid."),
("welsh-carson-anderson-and-stowe","Welsh, Carson, Anderson & Stowe","https://www.wcas.com/","Welsh, Carson, Anderson & Stowe was founded in 1979 and focuses on healthcare and technology.","The long four-name partnership is shortened to WCAS.","Large navy serif capitals feel like an old-money bank."),
("stone-point-capital","Stone Point Capital","https://www.stonepoint.com/","Stone Point Capital is based in Greenwich, Connecticut, and focuses on financial services.","Small capitals in a serif look like a private bank.","The name feels like a place, which is a sign of stability."),
("platinum-equity","Platinum Equity","https://www.platinumequity.com/","Tom Gores founded Platinum Equity in Beverly Hills in 1995.","An energetic handwritten script is surprising for a buyout firm.","The long swash under the name looks like a signature."),
("american-securities","American Securities","https://www.american-securities.com/","American Securities was founded in New York in 1994.","A stylised A with a diagonal stripe feels patriotic and fast.","Two words stacked give a long name a compact shape."),
("blue-owl","Blue Owl","https://www.blueowl.com/","Blue Owl was created in 2021 through a merger of Owl Rock and Dyal Capital.","A small owl icon is a direct picture of the name.","Widely spaced capitals feel calm and modern."),
("sixth-street","Sixth Street","https://sixthstreet.com/","Sixth Street began in 2009 as the credit arm of TPG and became an independent firm in 2020.","A geometric cube icon sits next to the name.","The name feels like a New York address and not a finance brand."),
("oaktree","Oaktree","https://www.oaktreecapital.com/","Howard Marks and colleagues founded Oaktree in Los Angeles in 1995.","A green tree icon is a literal picture of the name.","The small line \"Part of Brookfield\" shows its recent change of ownership."),
("cerberus","Cerberus","https://www.cerberus.com/","Stephen Feinberg founded Cerberus in New York in 1992, named after the three-headed dog in Greek myth.","A heavy, rounded lowercase wordmark feels modern and bold.","The name is a myth reference, but the logo has no dog."),
("clearlake-capital","Clearlake Capital","https://www.clearlake.com/","Clearlake Capital was founded in Santa Monica, California, in 2006.","A mountain and lake image gives a literal picture of the name.","The pale blue gradient feels calm and clear."),
("l-catterton","L Catterton","https://www.lcatterton.com/","L Catterton was formed in 2016 when Catterton partnered with LVMH Group's L Capital.","A blue L in a box links to the LVMH family.","A classic serif Catterton feels like a fashion brand."),
("centerbridge","Centerbridge","https://www.centerbridge.com/","Centerbridge was founded in New York in 2005.","A dotted arch above the name looks like a bridge.","Soft grey serif letters feel calm and trustworthy."),
("hig-capital","H.I.G. Capital","https://www.higcapital.com/","H.I.G. Capital was founded in Miami in 1993.","The letters sit inside small boxes, like a row of initials.","A thin vertical line and spaced CAPITAL add a stylish touch."),
("veritas-capital","Veritas Capital","https://www.veritascapital.com/","Veritas Capital was founded in New York in 1992 and focuses on government technology.","A striped V mark stands for Veritas, which means truth in Latin.","Spaced capitals under a symbol feel like a university seal."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 45
